# Cross-check: verify that 'patients' is always >= 'recovered' (valid denominator)
checks = {
    "patients >= recovered (all rows)": (df['patients'] >= df['recovered']).all(),
    "patients >= adverse_events (all rows)": (df['patients'] >= df['adverse_events']).all(),
    "any zero in patients": (df['patients'] == 0).any(),
    "recovery rate sample (recovered / patients)": (df['recovered'] / df['patients']).round(4).tolist(),
    "recovery rate sample (recovered / staff_hours)": (df['recovered'] / df['staff_hours']).round(4).tolist(),
}

for k, v in checks.items():
    print(f"{k}: {v}")
